DECODE_JSON(Variant) {
    ALLOW_NULL;
    CHECK_OBJECT;

    /* First search for the variant type in the json object. */
    size_t searchResultType = 0;
    status ret = lookAheadForKey(UA_JSONKEY_TYPE, ctx, parseCtx, &searchResultType);
    if(ret != UA_STATUSCODE_GOOD)
        return UA_STATUSCODE_BADDECODINGERROR;

    size_t size = (size_t)(parseCtx->tokenArray[searchResultType].end - parseCtx->tokenArray[searchResultType].start);

    /* check if size is zero or the type is not a number */
    if(size < 1 || parseCtx->tokenArray[searchResultType].type != JSMN_PRIMITIVE) {
        return UA_STATUSCODE_BADDECODINGERROR;
    }

    /*Parse the type*/
    UA_UInt64 idTypeDecoded = 0;
    char *idTypeEncoded = (char*)(ctx->pos + parseCtx->tokenArray[searchResultType].start);
    status typeDecodeStatus = atoiUnsigned(idTypeEncoded, size, &idTypeDecoded);

    /* value is not a valid number */
    if(typeDecodeStatus != UA_STATUSCODE_GOOD) {
        return typeDecodeStatus;
    }

    /*Set the type, Get the Type by nodeID!*/
    UA_NodeId typeNodeId = UA_NODEID_NUMERIC(0, (UA_UInt32)idTypeDecoded);
    const UA_DataType *bodyType = UA_findDataType(&typeNodeId);
    if(bodyType == NULL) {
        return UA_STATUSCODE_BADDECODINGERROR;
    }

    /*Set the type*/
    dst->type = bodyType;

    /* LookAhead BODY */
    /* Does the variant contain an array? */
    UA_Boolean isArray = false;
    UA_Boolean isBodyNull = false;

    /* Search for body */
    size_t searchResultBody = 0;
    ret = lookAheadForKey(UA_JSONKEY_BODY, ctx, parseCtx, &searchResultBody);
    if(ret == UA_STATUSCODE_GOOD) { /* body found */
        /* get body token */
        jsmntok_t bodyToken = parseCtx->tokenArray[searchResultBody];

        /*BODY is null?*/
        if(isJsonTokenNull(ctx, &bodyToken)) {
            dst->data = NULL;
            isBodyNull = true;
        }

        if(bodyToken.type == JSMN_ARRAY) {
            isArray = true;

            size_t arraySize = 0;
            arraySize = (size_t)parseCtx->tokenArray[searchResultBody].size;
            dst->arrayLength = arraySize;
        }
    } else {
        /*TODO: no body? set value NULL?*/
        return UA_STATUSCODE_BADDECODINGERROR;
    }

    /* LookAhead DIMENSION */
    UA_Boolean hasDimension = false;

    /* Has the variant dimension? */
    size_t searchResultDim = 0;
    ret = lookAheadForKey(UA_JSONKEY_DIMENSION, ctx, parseCtx, &searchResultDim);
    if(ret == UA_STATUSCODE_GOOD) {
        hasDimension = true;
        size_t dimensionSize = 0;
        dimensionSize = (size_t)parseCtx->tokenArray[searchResultDim].size;
        dst->arrayDimensionsSize = dimensionSize;
    }

    /* no array but has dimension. error? */
    if(!isArray && hasDimension)
        return UA_STATUSCODE_BADDECODINGERROR;

    /* Get the datatype of the content. The type must be a builtin data type.
    * All not-builtin types are wrapped in an ExtensionObject. */
    if(bodyType->typeKind > UA_TYPES_DIAGNOSTICINFO)
        return UA_STATUSCODE_BADDECODINGERROR;

    /* A variant cannot contain a variant. But it can contain an array of
        * variants */
    if(bodyType->typeKind == UA_DATATYPEKIND_VARIANT && !isArray)
        return UA_STATUSCODE_BADDECODINGERROR;

    if(isArray) {
        DecodeEntry entries[3] = {
            {UA_JSONKEY_TYPE, NULL, NULL, false, NULL},
            {UA_JSONKEY_BODY, &dst->data, (decodeJsonSignature) Array_decodeJson, false, NULL},
            {UA_JSONKEY_DIMENSION, &dst->arrayDimensions,
             (decodeJsonSignature) VariantDimension_decodeJson, false, NULL}};

        if(!hasDimension) {
            ret = decodeFields(ctx, parseCtx, entries, 2, bodyType); /*use first 2 fields*/
        } else {
            ret = decodeFields(ctx, parseCtx, entries, 3, bodyType); /*use all fields*/
        }
    } else if(bodyType->typeKind != UA_DATATYPEKIND_EXTENSIONOBJECT) {
        /* Allocate Memory for Body */
        if(!isBodyNull) {
            dst->data = UA_new(bodyType);
            if(!dst->data)
                return UA_STATUSCODE_BADOUTOFMEMORY;
        }

        DecodeEntry entries[2] = {{UA_JSONKEY_TYPE, NULL, NULL, false, NULL},
            {UA_JSONKEY_BODY, dst->data, (decodeJsonSignature) decodeJsonInternal, false, NULL}};
        ret = decodeFields(ctx, parseCtx, entries, 2, bodyType);
    } else { /* extensionObject */
        DecodeEntry entries[2] = {{UA_JSONKEY_TYPE, NULL, NULL, false, NULL},
            {UA_JSONKEY_BODY, dst,
             (decodeJsonSignature) Variant_decodeJsonUnwrapExtensionObject, false, NULL}};
        ret = decodeFields(ctx, parseCtx, entries, 2, bodyType);
    }
    return ret;
}

DECODE_JSON(DataValue) {
    ALLOW_NULL;
    CHECK_OBJECT;

    DecodeEntry entries[6] = {
       {UA_JSONKEY_VALUE, &dst->value, (decodeJsonSignature) Variant_decodeJson, false, NULL},
       {UA_JSONKEY_STATUS, &dst->status, (decodeJsonSignature) StatusCode_decodeJson, false, NULL},
       {UA_JSONKEY_SOURCETIMESTAMP, &dst->sourceTimestamp, (decodeJsonSignature) DateTime_decodeJson, false, NULL},
       {UA_JSONKEY_SOURCEPICOSECONDS, &dst->sourcePicoseconds, (decodeJsonSignature) UInt16_decodeJson, false, NULL},
       {UA_JSONKEY_SERVERTIMESTAMP, &dst->serverTimestamp, (decodeJsonSignature) DateTime_decodeJson, false, NULL},
       {UA_JSONKEY_SERVERPICOSECONDS, &dst->serverPicoseconds, (decodeJsonSignature) UInt16_decodeJson, false, NULL}};

    status ret = decodeFields(ctx, parseCtx, entries, 6, type);

Variant_decodeJsonUnwrapExtensionObject(UA_Variant *dst, const UA_DataType *type,
                                        CtxJson *ctx, ParseCtx *parseCtx, UA_Boolean moveToken) {
    (void) type, (void) moveToken;
    /*EXTENSIONOBJECT POSITION!*/
    UA_UInt16 old_index = parseCtx->index;
    UA_Boolean typeIdFound;

    /* Decode the DataType */
    UA_NodeId typeId;
    UA_NodeId_init(&typeId);

    size_t searchTypeIdResult = 0;
    status ret = lookAheadForKey(UA_JSONKEY_TYPEID, ctx, parseCtx, &searchTypeIdResult);

    if(ret != UA_STATUSCODE_GOOD) {
        /*No Typeid found*/
        typeIdFound = false;
        /*return UA_STATUSCODE_BADDECODINGERROR;*/
    } else {
        typeIdFound = true;
        /* parse the nodeid */
        parseCtx->index = (UA_UInt16)searchTypeIdResult;
        ret = NodeId_decodeJson(&typeId, &UA_TYPES[UA_TYPES_NODEID], ctx, parseCtx, true);
        if(ret != UA_STATUSCODE_GOOD) {
            UA_NodeId_deleteMembers(&typeId);
            return ret;
        }

        /*restore index, ExtensionObject position*/
        parseCtx->index = old_index;
    }

    /* ---Decode the EncodingByte--- */
    if(!typeIdFound)
        return UA_STATUSCODE_BADDECODINGERROR;

    UA_Boolean encodingFound = false;
    /*Search for Encoding*/
    size_t searchEncodingResult = 0;
    ret = lookAheadForKey(UA_JSONKEY_ENCODING, ctx, parseCtx, &searchEncodingResult);

    UA_UInt64 encoding = 0;
    /*If no encoding found it is Structure encoding*/
    if(ret == UA_STATUSCODE_GOOD) { /*FOUND*/
        encodingFound = true;
        char *extObjEncoding = (char*)(ctx->pos + parseCtx->tokenArray[searchEncodingResult].start);
        size_t size = (size_t)(parseCtx->tokenArray[searchEncodingResult].end
                               - parseCtx->tokenArray[searchEncodingResult].start);
        atoiUnsigned(extObjEncoding, size, &encoding);
    }

    const UA_DataType *typeOfBody = UA_findDataType(&typeId);

    if(encoding == 0 || typeOfBody != NULL) {
        /*This value is 0 if the body is Structure encoded as a JSON object (see 5.4.6).*/
        /* Found a valid type and it is structure encoded so it can be unwrapped */
        dst->type = typeOfBody;

        /* Allocate memory for type*/
        dst->data = UA_new(dst->type);
        if(!dst->data) {
            UA_NodeId_deleteMembers(&typeId);
            return UA_STATUSCODE_BADOUTOFMEMORY;
        }

        /* Decode the content */
        UA_NodeId nodeIddummy;
        DecodeEntry entries[3] =
            {
             {UA_JSONKEY_TYPEID, &nodeIddummy, (decodeJsonSignature) NodeId_decodeJson, false, NULL},
             {UA_JSONKEY_BODY, dst->data,
              (decodeJsonSignature) decodeJsonJumpTable[dst->type->typeKind], false, NULL},
             {UA_JSONKEY_ENCODING, NULL, NULL, false, NULL}};

        ret = decodeFields(ctx, parseCtx, entries, encodingFound ? 3:2, typeOfBody);
        if(ret != UA_STATUSCODE_GOOD) {
            UA_free(dst->data);
        }
    } else if(encoding == 1 || encoding == 2 || typeOfBody == NULL) {
        UA_NodeId_deleteMembers(&typeId);

        /* decode as ExtensionObject */
        dst->type = &UA_TYPES[UA_TYPES_EXTENSIONOBJECT];

        /* Allocate memory for extensionobject*/
        dst->data = UA_new(dst->type);
        if(!dst->data)
            return UA_STATUSCODE_BADOUTOFMEMORY;

        /* decode: Does not move tokenindex. */
        ret = DECODE_DIRECT_JSON(dst->data, ExtensionObject);
        if(ret != UA_STATUSCODE_GOOD)
            UA_free(dst->data);

message:
I am thinking...: Now I see the bug clearly. Let me trace through the code:

In `Variant_decodeJsonUnwrapExtensionObject`:

1. It looks for `TypeId` and `Encoding` fields
2. If `encoding == 0 || typeOfBody != NULL`, it unwraps the extension object:
   - Sets `dst->type = typeOfBody`
   - Allocates `dst->data = UA_new(dst->type)`
   - Calls `decodeFields` to decode the body
   - If `decodeFields` fails, it frees `dst->data` but does NOT reset `dst->type` or `dst->data`

3. If `encoding == 1 || encoding == 2 || typeOfBody == NULL`, it keeps it as an ExtensionObject:
   - Sets `dst->type = &UA_TYPES[UA_TYPES_EXTENSIONOBJECT]`
   - Allocates `dst->data = UA_new(dst->type)`
   - Decodes the body as an ExtensionObject
   - If decoding fails, it frees `dst->data` but does NOT reset `dst->type` or `dst->data`

The bug is in case 2 (and also case 3): when `decodeFields` fails, `dst->data` is freed but `dst->type` is NOT reset to NULL. The function returns the error code. But the caller (`Variant_decodeJson`) checks the return value and if it's not GOOD, it returns early. The fuzzer only calls `UA_Variant_deleteMembers` if the return is GOOD.

So the bug is NOT triggered when `decodeFields` fails. The bug must be triggered when `decodeFields` SUCCEEDS.

Wait, let me re-read the code. When `decodeFields` succeeds, the function returns `ret` which is `UA_STATUSCODE_GOOD`. The variant has `dst->type` set to the unwrapped type and `dst->data` pointing to the decoded data. This should be correct.

But wait - what if the body contains a nested ExtensionObject that also gets unwrapped? The nested ExtensionObject would be decoded by `decodeJsonJumpTable[dst->type->typeKind]`. If the nested type contains an ExtensionObject member, it would be decoded by `ExtensionObject_decodeJson`.

In `ExtensionObject_decodeJson`, when the extension object is decoded as a structure:
```c
dst->content.decoded.data = UA_new(typeOfBody);
...
DecodeEntry entries[2] = {
    {UA_JSONKEY_TYPEID, &typeId_dummy, ...},
    {UA_JSONKEY_BODY, dst->content.decoded.data,
     (decodeJsonSignature) decodeJsonJumpTable[typeOfBody->typeKind], ...}
};
return decodeFields(ctx, parseCtx, entries, 2, typeOfBody);
```

This allocates memory for the decoded type and decodes the body into it. If the body contains a LocalizedText, it's decoded correctly.

But what if the body contains an array? The `decodeJsonJumpTable[typeOfBody->typeKind]` would be called. If `typeOfBody` is a structure type, the jump table would call the structure's decode function, which would try to decode the body as an object. If the body is an array, this would fail.

Hmm, but the structure's decode function would handle array members correctly because it uses `decodeFields` which handles arrays.

OK, let me think about this differently. The crash is "Heap-use-after-free READ 8 in LocalizedText_clear". This means a LocalizedText struct is being read after it has been freed.

Let me look at the `Variant_clear` function:

```c
Variant_clear(UA_Variant *p, const UA_DataType *_) {
    if(p->storageType != UA_VARIANT_DATA)
        return;
    if(p->type && p->data > UA_EMPTY_ARRAY_SENTINEL) {
        if(p->arrayLength == 0)
            p->arrayLength = 1;
        UA_Array_delete(p->data, p->arrayLength, p->type);
        p->data = NULL;
    }
    if((void*)p->arrayDimensions > UA_EMPTY_ARRAY_SENTINEL)
        UA_free(p->arrayDimensions);
}
```

`UA_Array_delete` calls `UA_clear` on each element, which calls the type's clear function. For a type that contains LocalizedText, the clear function would call `LocalizedText_clear` on each LocalizedText member.

The use-after-free happens when `p->data` points to freed memory but `p->type` is still valid. This would happen if:
1. The variant's data was freed but the variant's type and data pointers were not reset
2. `Variant_clear` is called on this variant

But the fuzzer only calls `UA_Variant_deleteMembers` if `UA_decodeJson` returns GOOD. So the decode must succeed.

Wait, let me look at the `Variant_decodeJsonUnwrapExtensionObject` function again. When `encoding == 0 || typeOfBody != NULL`:

```c
dst->type = typeOfBody;
dst->data = UA_new(dst->type);
...
ret = decodeFields(ctx, parseCtx, entries, encodingFound ? 3:2, typeOfBody);
if(ret != UA_STATUSCODE_GOOD) {
    UA_free(dst->data);
}
return ret;
```

If `decodeFields` fails, `dst->data` is freed but `dst->type` is NOT reset. The function returns the error. The caller (`Variant_decodeJson`) checks the return value and if it's not GOOD, it returns early.

But what if `decodeFields` succeeds? Then `dst->data` points to valid memory and `dst->type` is set correctly. This should be fine.

Unless... the `decodeFields` function decodes the body, and the body contains a nested structure that has already been freed. But that doesn't make sense because the body is decoded from the JSON input.

Let me think about this from a completely different angle. What if the issue is with how `Variant_decodeJsonUnwrapExtensionObject` handles the case where the body is an array?

Looking at the decode entries:
```c
DecodeEntry entries[3] = {
    {UA_JSONKEY_TYPEID, &nodeIddummy, (decodeJsonSignature) NodeId_decodeJson, false, NULL},
    {UA_JSONKEY_BODY, dst->data,
     (decodeJsonSignature) decodeJsonJumpTable[dst->type->typeKind], false, NULL},
    {UA_JSONKEY_ENCODING, NULL, NULL, false, NULL}
};
```

The body is decoded using `decodeJsonJumpTable[dst->type->typeKind]`. If `dst->type` is a structure type, this would decode the body as that structure. But what if the body is actually an array?

In the JSON, the body could be an array. The `decodeJsonJumpTable` for a structure type would try to decode it as an object, which would fail. But what if the structure type has a member that is an array?

Actually, I think the issue might be simpler. Let me look at the `Variant_decodeJsonUnwrapExtensionObject` function again:

```c
if(encoding == 0 || typeOfBody != NULL) {
    dst->type = typeOfBody;
    dst->data = UA_new(dst->type);
    ...
    ret = decodeFields(ctx, parseCtx, entries, encodingFound ? 3:2, typeOfBody);
    if(ret != UA_STATUSCODE_GOOD) {
        UA_free(dst->data);
    }
}
```

What if `typeOfBody` is NULL? The condition `encoding == 0 || typeOfBody != NULL` would be true if `encoding == 0` even if `typeOfBody` is NULL. In that case:
- `dst->type = NULL`
- `UA_new(NULL)` - this would likely crash or return NULL

But wait, `typeOfBody` is set from `UA_findDataType(&typeId)`. If the typeId is not found, `typeOfBody` would be NULL. But the code checks `if(!typeIdFound)` earlier and returns if not found. So `typeIdFound` must be true for the code to reach this point. But `typeIdFound` being true doesn't guarantee that `UA_findDataType` returns non-NULL.

Actually, looking at the code:
```c
if(!typeIdFound)
    return UA_STATUSCODE_BADDECODINGERROR;
```

So `typeIdFound` must be true. But `typeIdFound` is set to true when `lookAheadForKey` succeeds for `TypeId`. This doesn't guarantee that `UA_findDataType` returns non-NULL.

If `typeOfBody` is NULL and `encoding == 0`:
- `dst->type = NULL`
- `UA_new(NULL)` - this would likely crash

But this would crash during decoding, not during cleanup. So this is not the reported bug.

Let me think about this more carefully. The crash is in `LocalizedText_clear` during cleanup after successful decoding. This means:
1. `UA_decodeJson` returns GOOD
2. `UA_Variant_deleteMembers` is called
3. `Variant_clear` is called
4. `UA_Array_delete` is called
5. `UA_clear` is called for each element
6. `LocalizedText_clear` is called
7. READ 8 from freed memory

For this to happen, the variant must contain data of a type that has LocalizedText members. The data must be in freed memory.

Let me look at the `Variant_decodeJsonUnwrapExtensionObject` function one more time. When it unwraps an extension object:

```c
dst->type = typeOfBody;
dst->data = UA_new(dst->type);
...
ret = decodeFields(ctx, parseCtx, entries, encodingFound ? 3:2, typeOfBody);
if(ret != UA_STATUSCODE_GOOD) {
    UA_free(dst->data);
}
return ret;
```

If `decodeFields` succeeds, `dst->data` points to valid memory. But what if `decodeFields` decodes the body, and the body contains a field that is also an ExtensionObject that gets unwrapped?

Wait, the body is decoded using `decodeJsonJumpTable[dst->type->typeKind]`. If `dst->type` is a structure type, this would call the structure's decode function. The structure's decode function would decode each field of the structure. If one of the fields is an ExtensionObject, it would be decoded by `ExtensionObject_decodeJson`.

In `ExtensionObject_decodeJson`, when the extension object is decoded as a structure:
```c
dst->content.decoded.data = UA_new(typeOfBody);
...
DecodeEntry entries[2] = {
    {UA_JSONKEY_TYPEID, &typeId_dummy, ...},
    {UA_JSONKEY_BODY, dst->content.decoded.data,
     (decodeJsonSignature) decodeJsonJumpTable[typeOfBody->typeKind], ...}
};
return decodeFields(ctx, parseCtx, entries, 2, typeOfBody);
```

This allocates memory for the decoded type and decodes the body into it. The decoded type could contain a LocalizedText member.

But what if the body contains an array of ExtensionObjects? The `decodeJsonJumpTable[typeOfBody->typeKind]` would be called. If `typeOfBody` is a structure type, the jump table would call the structure's decode function, which would try to decode the body as an object. If the body is an array, this would fail.

Unless the structure has a member that is an array of ExtensionObjects. In that case, the structure's decode function would handle the array member correctly.

OK, I think I need to actually try to trigger the bug. Let me look at what types contain LocalizedText and try to construct a JSON payload that triggers the use-after-free.

Actually, let me look at the `Variant_decodeJsonUnwrapExtensionObject` function one more time. I notice something:

```c
if(encoding == 0 || typeOfBody != NULL) {
    dst->type = typeOfBody;
    dst->data = UA_new(dst->type);
    ...
    ret = decodeFields(ctx, parseCtx, entries, encodingFound ? 3:2, typeOfBody);
    if(ret != UA_STATUSCODE_GOOD) {
        UA_free(dst->data);
    }
}
```

When `decodeFields` fails, `dst->data` is freed but `dst->type` is NOT reset. The function returns the error. But what if the caller doesn't check the error properly?

Looking at the caller (`Variant_decodeJson`):
```c
} else { /* extensionObject */
    DecodeEntry entries[2] = {{UA_JSONKEY_TYPE, NULL, NULL, false, NULL},
        {UA_JSONKEY_BODY, dst,
         (decodeJsonSignature) Variant_decodeJsonUnwrapExtensionObject, false, NULL}};
    ret = decodeFields(ctx, parseCtx, entries, 2, bodyType);
}
return ret;
```

`decodeFields` calls `Variant_decodeJsonUnwrapExtensionObject` via the function pointer. If `Variant_decodeJsonUnwrapExtensionObject` returns an error, `decodeFields` returns the error. `Variant_decodeJson` returns the error. The fuzzer checks the return value and doesn't call `UA_Variant_deleteMembers`.

So the error path is safe. The bug must be in the success path.

Wait, let me look at `decodeFields` more carefully. What if `decodeFields` calls `Variant_decodeJsonUnwrapExtensionObject` which succeeds, but then `decodeFields` itself fails for some other reason?

Looking at the decode entries in `Variant_decodeJson`:
```c
DecodeEntry entries[2] = {{UA_JSONKEY_TYPE, NULL, NULL, false, NULL},
    {UA_JSONKEY_BODY, dst,
     (decodeJsonSignature) Variant_decodeJsonUnwrapExtensionObject, false, NULL}};
ret = decodeFields(ctx, parseCtx, entries, 2, bodyType);
```

`decodeFields` processes the entries. The first entry is `Type` which is skipped (function is NULL). The second entry is `Body` which calls `Variant_decodeJsonUnwrapExtensionObject`. If this succeeds, `decodeFields` returns GOOD.

But what if there are additional fields in the JSON object that `decodeFields` doesn't expect? Looking at `decodeFields`:

```c
static status
decodeFields(CtxJson *ctx, ParseCtx *parseCtx, DecodeEntry *entries,
             size_t nEntries, const UA_DataType *type) {
    ...
    for(size_t i = 0; i < nEntries; i++) {
        ...
        ret = entries[i].function(ptr, type, ctx, parseCtx, true);
        if(ret != UA_STATUSCODE_GOOD)
            return ret;
    }
    return UA_STATUSCODE_GOOD;
}
```

It only processes the expected entries. Additional fields in the JSON are ignored.

OK, I'm going in circles. Let me try a different approach. Let me look at the `Variant_decodeJsonUnwrapExtensionObject` function and think about what happens when the body contains an array of LocalizedText.

When `encoding == 0` and `typeOfBody` is a structure type that contains an array of LocalizedText:
1. `dst->type = typeOfBody` (the structure type)
2. `dst->data = UA_new(dst->type)` (allocates memory for the structure)
3. The body is decoded using `decodeJsonJumpTable[dst->type->typeKind]` which is the structure's decode function
4. The structure's decode function decodes each field, including the array of LocalizedText
5. The array of LocalizedText is decoded by `Array_decodeJson` which allocates memory for the array elements

This should work correctly. The array elements are stored in memory allocated by `Array_decodeJson`.

But wait - what if the structure type is NOT the one that contains the array of LocalizedText? What if `typeOfBody` is a different type?

Actually, I think I've been overthinking this. Let me look at the actual crash report more carefully. The crash is "Heap-use-after-free READ 8 in LocalizedText_clear". The READ 8 means reading 8 bytes from freed memory. In `LocalizedText_clear`:

```c
LocalizedText_clear(UA_LocalizedText *p, const UA_DataType *_) {
    String_clear(&p->locale, NULL);
    String_clear(&p->text, NULL);
}
```

`String_clear`:
```c
String_clear(UA_String *p, const UA_DataType *_) {
    UA_free(p->data);
    p->data = NULL;
    p->length = 0;
}
```

Wait, `String_clear` reads `p->data` (a pointer) and frees it. If `p` itself is in freed memory, then reading `p->locale` would be a use-after-free READ.

But `p` is a pointer to a LocalizedText struct. If the LocalizedText struct is in freed memory, then reading `p->locale` (first 16 bytes) would be a use-after-free.

For this to happen, the memory containing the LocalizedText must have been freed but the pointer to it is still being used.

In the context of `Variant_clear`:
```c
UA_Array_delete(p->data, p->arrayLength, p->type);
```

`p->data` points to the variant's data. If `p->data` points to freed memory, then `UA_Array_delete` would access freed memory.

So the question is: how can `p->data` point to freed memory after a successful decode?

